mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.ORG_ID,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.ORG_NAME,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.ORG_ID = #{orgId}
AND T1.ACTIVE_YN = #{activeYn}

WHERE 1=1

  AND (UPPER(NVL(T1.PERSON_ID,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.PERSON_NAME,'')) LIKE '%'||UPPER(#{keyword})||'%' OR UPPER(NVL(T1.EMAIL,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.PERSON_ID = #{personId}
AND T1.ORG_ID = #{orgId}
AND T1.ACTIVE_YN = #{activeYn}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.ORG_ID AS ORG_ID, T1.ORG_NAME AS ORG_NAME, T1.PARENT_ORG_ID AS PARENT_ORG_ID, T1.ORG_TYPE_CD AS ORG_TYPE_CD,
           T1.ACTIVE_YN AS ACTIVE_YN, T1.REMARK AS REMARK, T1.REG_USER_ID AS REG_USER_ID, T1.REG_DTM AS REG_DTM,
           T1.CHG_USER_ID AS CHG_USER_ID, T1.CHG_DTM AS CHG_DTM
      FROM TB_IF_ORG_UNIT_PILOT T1

     ORDER BY T1.ORG_ID ASC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.PERSON_ID AS PERSON_ID, T1.PERSON_NAME AS PERSON_NAME, T1.ORG_ID AS ORG_ID, O.ORG_NAME AS ORG_NAME,
           T1.EMAIL AS EMAIL, T1.ROLE_CD AS ROLE_CD, T1.ACTIVE_YN AS ACTIVE_YN, T1.REMARK AS REMARK,
           T1.REG_USER_ID AS REG_USER_ID, T1.REG_DTM AS REG_DTM, T1.CHG_USER_ID AS CHG_USER_ID, T1.CHG_DTM AS CHG_DTM
      FROM TB_IF_PERSON_PILOT T1
      LEFT JOIN TB_IF_ORG_UNIT_PILOT O ON O.ORG_ID = T1.ORG_ID

     ORDER BY T1.PERSON_ID ASC
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

mapper.update:
UPDATE TB_IF_ORG_UNIT_PILOT SET ORG_NAME=#{orgName}, PARENT_ORG_ID=#{parentOrgId}, ORG_TYPE_CD=#{orgTypeCd},
  ACTIVE_YN=#{activeYn}, REMARK=#{remark}, CHG_USER_ID=#{chgUserId}, CHG_DTM=#{chgDtm}
 WHERE ORG_ID=#{orgId}

UPDATE TB_IF_PERSON_PILOT SET PERSON_NAME=#{personName}, ORG_ID=#{orgId}, EMAIL=#{email}, ROLE_CD=#{roleCd},
  ACTIVE_YN=#{activeYn}, REMARK=#{remark}, CHG_USER_ID=#{chgUserId}, CHG_DTM=#{chgDtm}
 WHERE PERSON_ID=#{personId}

UPDATE TB_IF_PERSON_PILOT SET ROLE_CD=#{roleCd},
  REMARK=#{remark}, CHG_USER_ID=#{chgUserId}, CHG_DTM=#{chgDtm}
 WHERE PERSON_ID=#{personId}
